// ── AUTOCOMPLETE ENGINE ───────────────────────────────────────
function initAddressBookAutocomplete() {
  const input    = document.getElementById('receiverCompany');
  const dropdown = document.createElement('div');
  dropdown.id    = 'addressDropdown';
  dropdown.style.cssText = `
    position:absolute;background:#fff;border:1px solid var(--border,#dce3ec);
    border-radius:6px;box-shadow:0 8px 24px rgba(0,0,0,.12);
    max-height:280px;overflow-y:auto;z-index:999;width:100%;left:0;top:100%;
    display:none;font-family:'Barlow',sans-serif;font-size:13px
  `;
  input.parentElement.style.position = 'relative';
  input.parentElement.appendChild(dropdown);

  input.addEventListener('input', () => {
    const q = input.value.trim().toLowerCase();
    if (q.length < 2) { dropdown.style.display = 'none'; return; }

    const matches = DHL_ADDRESS_BOOK.filter(c =>
      (c.name    || '').toLowerCase().includes(q) ||
      (c.company || '').toLowerCase().includes(q) ||
      (c.city    || '').toLowerCase().includes(q) ||
      (c.email   || '').toLowerCase().includes(q)
    ).slice(0, 8);

    if (!matches.length) { dropdown.style.display = 'none'; return; }

    dropdown.innerHTML = matches.map((c, i) => `
      <div class="addr-item" data-idx="${i}"
        style="padding:10px 14px;cursor:pointer;border-bottom:1px solid #f0f0f0;
               display:flex;justify-content:space-between;align-items:center"
        onmouseenter="this.style.background='#f5f8ff'"
        onmouseleave="this.style.background='#fff'"
        onclick="fillReceiverFromBook(${JSON.stringify(c).replace(/'/g,'\\&apos;')})">
        <div>
          <div style="font-weight:700;color:#0d2137">${c.company || c.name}</div>
          <div style="font-size:11px;color:#607d8b">${c.name !== c.company && c.name ? c.name + ' · ' : ''}<span style="font-weight:600">${c.city}</span>${c.state ? ', ' + c.state : ''}</div>
          <div style="font-size:11px;color:#90a4ae">${c.email || ''}</div>
        </div>
        <div style="font-size:11px;font-weight:700;color:#1565c0;background:#e3f2fd;
                    padding:3px 8px;border-radius:12px;white-space:nowrap;margin-left:10px">
          ${c.countryCode}
        </div>
      </div>`).join('');

    dropdown.style.display = 'block';
  });

  // Close on outside click
  document.addEventListener('click', e => {
    if (!input.parentElement.contains(e.target)) dropdown.style.display = 'none';
  });
}

function fillReceiverFromBook(contact) {
  const set = (id, val) => { const el = document.getElementById(id); if (el && val) el.value = val; };

  set('receiverCompany',  contact.company || contact.name);
  set('receiverFullName', contact.name);
  set('receiverEmail',    contact.email);
  set('receiverPhone',    contact.phoneCode ? '+' + contact.phoneCode + contact.phone : contact.phone);
  set('receiverCity',     contact.city);
  set('receiverPostal',   contact.postalCode);
  set('receiverAddr1',    contact.address1);
  set('receiverAddr2',    contact.address2 || '');
  set('receiverProvince', contact.state || '');

  // Set country dropdown
  const countryEl = document.getElementById('receiverCountry');
  if (countryEl && contact.countryCode) {
    // Try to find the option
    const opt = Array.from(countryEl.options).find(o => o.value === contact.countryCode);
    if (opt) {
      countryEl.value = contact.countryCode;
    } else {
      // Add it if not in list
      const newOpt = document.createElement('option');
      newOpt.value = contact.countryCode;
      newOpt.text  = contact.countryCode;
      newOpt.selected = true;
      countryEl.appendChild(newOpt);
    }
  }

  // Hide dropdown and trigger cost recalc
  const dd = document.getElementById('addressDropdown');
  if (dd) dd.style.display = 'none';

  // Trigger pricing recalculation
  if (typeof calcCost === 'function') calcCost();
  if (typeof calcWeights === 'function') calcWeights();

  // Show confirmation toast
  showAddressToast(contact.company || contact.name);
}

function showAddressToast(name) {
  let toast = document.getElementById('addrToast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'addrToast';
    toast.style.cssText = `
      position:fixed;bottom:24px;right:24px;background:#2e7d32;color:#fff;
      padding:12px 20px;border-radius:8px;font-family:'Barlow',sans-serif;
      font-size:13px;font-weight:600;z-index:9999;
      box-shadow:0 4px 16px rgba(0,0,0,.2);transition:opacity .3s
    `;
    document.body.appendChild(toast);
  }
  toast.textContent = `✓ Address filled from: ${name}`;
  toast.style.opacity = '1';
  toast.style.display = 'block';
  setTimeout(() => { toast.style.opacity = '0'; setTimeout(() => toast.style.display='none', 300); }, 2500);
}

// Auto-init when DOM is ready
document.addEventListener('DOMContentLoaded', initAddressBookAutocomplete);



